document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("manipuri-modal"),t=document.getElementById("manipuri-modal-close"),n=document.getElementById("modal-title"),d=document.getElementById("modal-heading"),i=document.getElementById("modal-description"),o=document.querySelectorAll(".manipuri-gallery-item");if(e&&o.length>0){o.forEach(t=>{t.addEventListener("click",()=>{const o=t.getAttribute("data-title"),l=t.getAttribute("data-desc"),a=t.querySelector(".manipuri-gallery-overlay p").textContent;n.textContent=o,d.textContent=a,i.textContent=l,e.classList.add("active"),e.setAttribute("aria-hidden","false")})});const l=()=>{e.classList.remove("active"),e.setAttribute("aria-hidden","true")};t&&t.addEventListener("click",l),e.addEventListener("click",t=>{t.target===e&&l()}),document.addEventListener("keydown",t=>{"Escape"===t.key&&e.classList.contains("active")&&l()})}const l=document.getElementById("btn-scroll-top");l&&(window.addEventListener("scroll",()=>{window.scrollY>400?l.style.display="flex":l.style.display="none"}),l.addEventListener("click",()=>{window.scrollTo({top:0,behavior:"smooth"})}))});